def max_energy(beads):
    n = len(beads)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
                dp[i][j] = beads[i - 1]
            elif j == i + 1:
                dp[i][j] = beads[i - 1] * beads[j - 1]
            else:
                dp[i][j] = max(dp[i][k] + dp[k + 1][j] for k in range(i, j))

    return dp[1][n]

def polynomial_to_string(n, coeffs):
    result = ""
    for i in range(len(coeffs)):
        coeff = coeffs[i]
        if coeff != 0:
            if coeff < 0:
                result += "-"
            elif i > 0:
                result += "+"
            abs_coeff = abs(coeff)
            if abs_coeff != 1 or i == 0:
                result += str(abs_coeff)
            if i > 0:
                result += "x"
                if i > 1:
                    result += "^" + str(i)
    return result

